// SVG (as generated by this app) → DXF R12 with LWPOLYLINE-free POLYLINE
// entities, so it opens in LightBurn, LaserGRBL, Inkscape, AutoCAD and
// most laser software. Curves are flattened to short segments.
//
// The SVG is laid out in a hidden element so the browser resolves every
// transform; shapes are sampled with getPointAtLength.

const SAMPLE_MM = 0.25          // max distance between points along curves
const MAX_POINTS_PER_PATH = 20000

const LAYERS = {
  CORTE: { color: 1 },          // red
  GRABADO: { color: 7 },        // black/white
}

function layerOf(node) {
  for (let n = node; n && n.nodeType === 1; n = n.parentNode) {
    const stroke = n.getAttribute && n.getAttribute('stroke')
    if (stroke && /^#f00(0{3})?$/i.test(stroke)) return 'CORTE'
    if (n.classList && n.classList.contains('layer-cut')) return 'CORTE'
  }
  return 'GRABADO'
}

function splitSubpaths(d) {
  return d.split(/(?=M)/).map(s => s.trim()).filter(Boolean)
}

function samplePath(el, matrix, ns) {
  const length = el.getTotalLength()
  if (!length) return []
  const scale = Math.sqrt(Math.abs(matrix.a * matrix.d - matrix.b * matrix.c)) || 1
  const steps = Math.min(MAX_POINTS_PER_PATH, Math.max(2, Math.ceil((length * scale) / SAMPLE_MM)))
  const points = []
  for (let i = 0; i <= steps; i++) {
    const p = el.getPointAtLength((length * i) / steps)
    const q = new DOMPoint(p.x, p.y).matrixTransform(matrix)
    points.push([q.x, q.y])
  }
  return points
}

function toPolylines(svgText) {
  const doc = new DOMParser().parseFromString(svgText, 'image/svg+xml')
  const root = doc.documentElement
  const ns = 'http://www.w3.org/2000/svg'
  const holder = document.createElement('div')
  holder.style.cssText = 'position:absolute;left:-100000px;top:0;width:10px;height:10px;overflow:hidden;visibility:hidden'
  const svg = document.importNode(root, true)
  svg.setAttribute('width', root.viewBox.baseVal.width)
  svg.setAttribute('height', root.viewBox.baseVal.height)
  holder.appendChild(svg)
  document.body.appendChild(holder)

  const shapes = []
  let skippedImages = 0
  try {
    const rootInverse = svg.getScreenCTM().inverse()
    svg.querySelectorAll('path, rect, circle, ellipse, line, polyline, polygon').forEach(node => {
      const matrix = rootInverse.multiply(node.getScreenCTM())
      const layer = layerOf(node)
      if (node.tagName === 'path') {
        // Each subpath is sampled on its own so jumps between them are not drawn.
        splitSubpaths(node.getAttribute('d') || '').forEach(d => {
          const part = document.createElementNS(ns, 'path')
          part.setAttribute('d', d)
          node.parentNode.appendChild(part)
          const points = samplePath(part, matrix, ns)
          part.remove()
          if (points.length > 1) shapes.push({ layer, points, closed: /z\s*$/i.test(d) })
        })
      } else {
        const points = samplePath(node, matrix, ns)
        if (points.length > 1) shapes.push({ layer, points, closed: node.tagName !== 'line' && node.tagName !== 'polyline' })
      }
    })
    skippedImages = svg.querySelectorAll('image').length
  } finally {
    holder.remove()
  }
  return { shapes, height: root.viewBox.baseVal.height, skippedImages }
}

const n = v => Number(v.toFixed(4)).toString()

export function svgToDxf(svgText) {
  const { shapes, height, skippedImages } = toPolylines(svgText)
  const out = [
    '0', 'SECTION', '2', 'HEADER',
    '9', '$INSUNITS', '70', '4',            // millimetres
    '0', 'ENDSEC',
    '0', 'SECTION', '2', 'TABLES',
    '0', 'TABLE', '2', 'LAYER', '70', String(Object.keys(LAYERS).length),
  ]
  Object.entries(LAYERS).forEach(([name, { color }]) => {
    out.push('0', 'LAYER', '2', name, '70', '0', '62', String(color), '6', 'CONTINUOUS')
  })
  out.push('0', 'ENDTAB', '0', 'ENDSEC', '0', 'SECTION', '2', 'ENTITIES')

  shapes.forEach(({ layer, points, closed }) => {
    // DXF's Y axis points up; flip so the drawing is not mirrored.
    out.push('0', 'POLYLINE', '8', layer, '66', '1', '70', closed ? '1' : '0')
    points.forEach(([x, y]) => out.push('0', 'VERTEX', '8', layer, '10', n(x), '20', n(height - y)))
    out.push('0', 'SEQEND', '8', layer)
  })
  out.push('0', 'ENDSEC', '0', 'EOF')
  return { dxf: out.join('\n'), shapes: shapes.length, skippedImages }
}

export function downloadDxfs(svgs, baseName) {
  let skipped = 0
  svgs.forEach((svg, i) => {
    const { dxf, skippedImages } = svgToDxf(svg)
    skipped += skippedImages
    const url = URL.createObjectURL(new Blob([dxf], { type: 'application/dxf' }))
    const a = document.createElement('a')
    a.download = svgs.length > 1 ? `${baseName}_plancha${i + 1}.dxf` : `${baseName}.dxf`
    a.href = url
    document.body.appendChild(a)
    a.click()
    a.remove()
    setTimeout(() => URL.revokeObjectURL(url), 1000)
  })
  return { skippedImages: skipped }
}
